  final Object? error;
  final bool noWork;
  final String? summary;
  final int hiddenRecords;
  final int summarizedMessages;
}

/// [_AttemptOutcome] plus the fallback label that won (smol/main), for
/// the pass report. A class for the same record_size reason (issue
