  CustomMessageRecord() => markerKinds.notice,
  CompactCheckpointRecord() => markerKinds.checkpoint,
  CompactionRecord() => markerKinds.legacyCheckpoint,
  BranchSummaryRecord() => markerKinds.branchSummary,
