// Copyright (c) 2026, the Flutter Agent Harness authors.
// Use of this source code is governed by a MIT license that can be found in
// the LICENSE file.

/// gh-209 — the emergency compaction tier: deterministic mid-turn
/// relief with NO language model anywhere.
///
/// AC coverage:
/// - the relief completes deterministically (no LM call is even
///   possible: the tier takes no judge/summarizer) with a bounded wall
///   time;
/// - keep-N-recent per tool class hides the stalest groups first;
/// - repeated reads of the same path dedup (newest successful copy
///   survives), including the negative cases (a failed newest read must
///   NOT fold its older good copy; different paths never dedup);
/// - the shared invariants hold: pair groups hide atomically, real user
///   turns and the protected tail and pinned expansions never hide;
/// - the local trim valve bounds the live context when hides cannot;
/// - session survival (owner directive): the tier writes ONLY additive
///   hidden-range records — an old (large) session file stays
///   byte-identical apart from the appended records.
library;

import 'dart:convert';

import 'package:flutter_agent_harness/flutter_agent_harness.dart';
import 'package:flutter_agent_harness/src/compaction/emergency_relief.dart';
import 'package:flutter_agent_harness/src/compaction/structured/judge.dart'
    show hideProtectTailEntries;
import 'package:test/test.dart';

AssistantMessage _assistant(
  String text, {
  List<ToolCall>? calls,
}) {
  return AssistantMessage(
    content: [TextContent(text: text), ...?calls],
    api: 'anthropic-messages',
    provider: 'p',
    model: 'm1',
    usage: Usage.zero,
    stopReason: StopReason.stop,
    timestamp: DateTime.utc(2026),
  );
}

ToolResultMessage _result(
  String callId,
  String name,
  String text, {
  bool isError = false,
}) {
  return ToolResultMessage(
    toolCallId: callId,
    toolName: name,
    content: [TextContent(text: text)],
    isError: isError,
    timestamp: DateTime.utc(2026),
  );
}

/// Window 8000, reserve 2000 -> trigger 6000; keep-recent 2000.
const _settings = CompactionSettings(
  enabled: true,
  reserveTokens: 2000,
  keepRecentTokens: 2000,
);

AgentState _state(List<Message> messages) => AgentState(
  model: Model(
    id: 'm1',
    name: 'm1',
    api: 'anthropic-messages',
    provider: 'p',
    baseUrl: 'http://localhost:1',
    contextWindow: 8000,
    maxTokens: 4096,
  ),
  messages: messages,
);

/// The heavy filler tail: enough assistant text to sit inside the
/// protected tail so the hides have to work on the OLDER records.
List<Message> _tail({int count = 4}) => [
  for (var i = 0; i < count; i++) _assistant('final analysis line $i'),
];

void main() {
  late MemoryFileSystem fs;
  late JsonlSessionRepo repo;

  setUp(() {
    fs = MemoryFileSystem();
    repo = JsonlSessionRepo(fs: fs, sessionsRoot: '/sessions');
  });

  /// The dedup fixture: three reads of the SAME path plus a read of a
  /// different path, with enough filler to sit over the 6000 trigger.
  /// Groups (oldest first):
  /// 1. read a.dart (16k chars ≈ 4k tok)
  /// 2. read b.dart (16k chars ≈ 4k tok)
  /// 3. read a.dart again (16k chars ≈ 4k tok) — the newest a.dart
  /// 4. filler tail (kept by the protected tail)
  Future<(Session, AgentState)> dedupSession() async {
    final session = await repo.create(JsonlSessionCreateOptions(cwd: '/work'));
    await session.appendMessage(UserMessage.text('inspect the config'));
    await session.appendMessage(
      _assistant(
        'reading a',
        calls: [
          const ToolCall(
            id: 'r1',
            name: 'read',
            arguments: {'path': 'a.dart'},
          ),
        ],
      ),
    );
    await session.appendMessage(_result('r1', 'read', 'a' * 16000));
    await session.appendMessage(
      _assistant(
        'reading b',
        calls: [
          const ToolCall(
            id: 'r2',
            name: 'read',
            arguments: {'path': 'b.dart'},
          ),
        ],
      ),
    );
    await session.appendMessage(_result('r2', 'read', 'b' * 16000));
    await session.appendMessage(
      _assistant(
        'reading a again',
        calls: [
          const ToolCall(
            id: 'r3',
            name: 'read',
            arguments: {'path': './a.dart'},
          ),
        ],
      ),
    );
    await session.appendMessage(_result('r3', 'read', 'a2' * 8000));
    for (final message in _tail()) {
      await session.appendMessage(message);
    }
    final messages = await session.buildContextMessages();
    assert(
      estimateContextTokens(messages).tokens > 6000,
      'fixture must be over the trigger',
    );
    return (session, _state(messages));
  }

  group('dedup repeated reads', () {
    test('the older read of a path folds, the newest copy survives',
        () async {
      final (session, state) = await dedupSession();
      final relief = EmergencyRelief(
        session: session,
        state: state,
        window: 8000,
        settings: _settings,
        // Generous class keeps: the dedup must do the work here, not
        // the keep-N-recent pass.
        keepRecent: const {'read': 99, 'exec': 99, 'other': 99},
      );

      final outcome = await relief.run();

      expect(outcome.ok, isTrue);
      expect(outcome.alreadyUnder, isFalse);
      // Both older reads folded (a.dart r1 and b.dart r2 — r2 folds as a
      // stale keep-N candidate past its class budget... with keeps at 99
      // it must NOT — so exactly ONE path deduped, ONE group hidden).
      expect(outcome.dedupedPaths, 1, reason: 'only a.dart repeats');
      expect(outcome.hiddenGroups, 1);
      expect(outcome.hiddenRecords, 2, reason: 'carrier + result atomically');
      expect(outcome.usedTrimValve, isFalse);

      final messages = state.messages;
      final markerTexts = messages
          .whereType<UserMessage>()
          .map((m) => m.content as String)
          .where((text) => text.contains(':hidden'))
          .toList();
      // The r1 pair became two markers.
      expect(markerTexts, hasLength(2));
      // The newest a.dart copy (r3) is still live and readable.
      final liveReads = messages
          .whereType<ToolResultMessage>()
          .where((m) => m.toolName == 'read')
          .toList();
      expect(liveReads, hasLength(2));
      expect(liveReads.any((m) => m.content.first.toString().contains('a2')),
          isTrue, reason: 'the newest a.dart copy survives');
    });

    test('a failed newest read never folds its older good copy', () async {
      final session = await repo.create(JsonlSessionCreateOptions(cwd: '/work'));
      await session.appendMessage(UserMessage.text('inspect the config'));
      await session.appendMessage(
        _assistant(
          'reading a',
          calls: [
            const ToolCall(
              id: 'r1',
              name: 'read',
              arguments: {'path': 'a.dart'},
            ),
          ],
        ),
      );
      await session.appendMessage(_result('r1', 'read', 'good content' * 900));
      await session.appendMessage(
        _assistant(
          'reading a again',
          calls: [
            const ToolCall(
              id: 'r2',
              name: 'read',
              arguments: {'path': 'a.dart'},
            ),
          ],
        ),
      );
      // The NEWEST copy failed — it cannot answer for the path, so the
      // older good copy must stay live.
      await session.appendMessage(
        _result('r2', 'read', 'boom', isError: true),
      );
      for (final message in _tail()) {
        await session.appendMessage(message);
      }
      final state = _state(await session.buildContextMessages());
      final relief = EmergencyRelief(
        session: session,
        state: state,
        window: 8000,
        settings: _settings,
        keepRecent: const {'read': 99, 'exec': 99, 'other': 99},
      );

      final outcome = await relief.run();

      expect(outcome.dedupedPaths, 0);
      // Nothing else to hide (both groups sit inside the protected tail
      // budget with keeps at 99) — the run falls to the trim valve.
      expect(outcome.hiddenRecords, 0);
      final liveReads = state.messages
          .whereType<ToolResultMessage>()
          .where((m) => m.toolName == 'read' && !m.isError)
          .toList();
      expect(
        liveReads,
        isNotEmpty,
        reason: 'the older successful read must stay live',
      );
    });

    test('different paths never dedup each other', () async {
      final (session, state) = await dedupSession();
      final relief = EmergencyRelief(
        session: session,
        state: state,
        window: 8000,
        settings: _settings,
        keepRecent: const {'read': 99, 'exec': 99, 'other': 99},
      );

      final outcome = await relief.run();

      // Only a.dart repeats (r1 vs r3): b.dart (r2) must stay live.
      expect(outcome.dedupedPaths, 1);
      final liveReads = state.messages
          .whereType<ToolResultMessage>()
          .where((m) => m.toolName == 'read')
          .toList();
      expect(
        liveReads.any(
          (m) => (m.content.first as TextContent).text.startsWith('b'),
        ),
        isTrue,
        reason: 'the single b.dart read must stay live',
      );
    });
  });

  group('keep-N-recent per tool class', () {
    /// Four read groups (a→d), four bash groups (1→4), a user ask and a
    /// small tail — over the trigger, with keeps at 1/1 the older groups
    /// fold stalest-first.
    Future<(Session, AgentState, List<String>)> multiToolSession({
      Map<String, int> keepRecent = const {'read': 1, 'exec': 1},
    }) async {
      final session = await repo.create(JsonlSessionCreateOptions(cwd: '/work'));
      final carrierIds = <String>[];
      var callId = 0;
      Future<void> group(String name, String tool, String payload) async {
        final id = 'c${++callId}';
        carrierIds.add(id);
        await session.appendMessage(
          _assistant(
            name,
            calls: [
              ToolCall(
                id: id,
                name: tool,
                arguments: {'path': '$name.txt'},
              ),
            ],
          ),
        );
        await session.appendMessage(_result(id, tool, payload));
      }

      await session.appendMessage(UserMessage.text('sweep the repo'));
      await group('ra', 'read', 'a' * 8000);
      await group('rb', 'read', 'b' * 8000);
      await group('rc', 'read', 'c' * 8000);
      await group('rd', 'read', 'd' * 8000);
      await group('sa', 'bash', '1' * 8000);
      await group('sb', 'bash', '2' * 8000);
      await group('sc', 'bash', '3' * 8000);
      await group('sd', 'bash', '4' * 8000);
      await session.appendMessage(_assistant('wrapping up'));
      final state = _state(await session.buildContextMessages());
      return (session, state, carrierIds);
    }

    test('stalest-first hides past the per-class keep budget (multi-item)',
        () async {
      final (session, state, carrierIds) = await multiToolSession();
      final relief = EmergencyRelief(
        session: session,
        state: state,
        window: 8000,
        settings: _settings,
        keepRecent: const {'read': 1, 'exec': 1, 'other': 99},
      );

      final outcome = await relief.run();

      expect(outcome.ok, isTrue);
      // read keeps rd, exec keeps sd → 3 + 3 groups folded = 6 groups,
      // 12 records (each carrier + its result).
      expect(outcome.hiddenGroups, 6);
      expect(outcome.hiddenRecords, 12);
      // The per-class NEWEST copies stay live.
      final live = state.messages
          .whereType<ToolResultMessage>()
          .map((m) => m.toolCallId)
          .toSet();
      expect(live.contains('c8'), isTrue, reason: 'newest read kept');
      expect(live.contains('c4'), isFalse, reason: 'oldest read folded');
      expect(live.contains('c16'), isTrue, reason: 'newest bash kept');
      expect(live.contains('c12'), isFalse, reason: 'oldest bash folded');
      // Every folded record still sits in the session file — lossless.
      final fileText = fs
          .readAsStringSync('/sessions/${session.id}.jsonl');
      for (final id in carrierIds) {
        expect(fileText, contains('"$id"'));
      }
    });

    test('exempt user turns and the protected tail never hide', () async {
      final (session, state, _) = await multiToolSession();
      final userText = 'sweep the repo';
      final relief = EmergencyRelief(
        session: session,
        state: state,
        window: 8000,
        settings: _settings,
        keepRecent: const {'read': 1, 'exec': 1, 'other': 99},
      );

      await relief.run();

      // The real user turn stays live verbatim (F8).
      final liveUsers = state.messages
          .whereType<UserMessage>()
          .where((m) => (m.content as String) == userText)
          .toList();
      expect(liveUsers, hasLength(1));
      // The newest assistant line (inside the protected tail) stays live.
      final last = state.messages.last;
      expect(last, isA<AssistantMessage>());
      expect(
        (last as AssistantMessage).content.whereType<TextContent>().first.text,
        'wrapping up',
      );
    });
  });

  group('invariants and edges', () {
    test('already-under target: no-op outcome, nothing written', () async {
      final session = await repo.create(JsonlSessionCreateOptions(cwd: '/work'));
      await session.appendMessage(UserMessage.text('tiny'));
      final state = _state(await session.buildContextMessages());
      final relief = EmergencyRelief(
        session: session,
        state: state,
        window: 8000,
        settings: _settings,
      );

      final outcome = await relief.run();

      expect(outcome.ok, isTrue);
      expect(outcome.alreadyUnder, isTrue);
      expect(outcome.tokensBefore, outcome.tokensAfter);
      expect(outcome.hiddenRecords, 0);
    });

    test('unanswered carriers never hide (pair integrity)', () async {
      final session = await repo.create(JsonlSessionCreateOptions(cwd: '/work'));
      await session.appendMessage(UserMessage.text('run it'));
      await session.appendMessage(
        _assistant(
          'running',
          calls: [
            const ToolCall(id: 'live1', name: 'bash', arguments: {}),
          ],
        ),
      );
      // NO result for live1 — the carrier must never fold, whatever the
      // class budgets say.
      await session.appendMessage(_result('done1', 'bash', 'x' * 12000));
      await session.appendMessage(
        _assistant('again', calls: [
          const ToolCall(id: 'live2', name: 'bash', arguments: {}),
        ]),
      );
      await session.appendMessage(_result('live2', 'bash', 'y' * 12000));
      final state = _state(await session.buildContextMessages());
      final relief = EmergencyRelief(
        session: session,
        state: state,
        window: 8000,
        settings: _settings,
        keepRecent: const {'read': 1, 'exec': 0, 'other': 99},
      );

      final outcome = await relief.run();

      final liveCalls = state.messages
          .whereType<AssistantMessage>()
          .expand((m) => m.content.whereType<ToolCall>())
          .map((c) => c.id)
          .toSet();
      expect(liveCalls, contains('live1'));
      final results = state.messages
          .whereType<ToolResultMessage>()
          .map((m) => m.toolCallId)
          .toSet();
      // Pair integrity: the answered pair may fold atomically; the
      // unanswered call stays with NO orphan and NO unanswered pair.
      final calls = state.messages
          .map((m) {
            if (m is AssistantMessage) {
              return m.content.whereType<ToolCall>().map((c) => c.id);
            }
            return <String>[];
          })
          .expand((x) => x)
          .toSet();
      for (final callId in calls) {
        expect(
          results,
          contains(callId),
          reason: 'no unanswered call may ride the wire after relief',
        );
      }
      expect(outcome.usedTrimValve || outcome.ok, isTrue);
    });

    test('trim valve bounds the live context when hides free nothing',
        () async {
      final session = await repo.create(JsonlSessionCreateOptions(cwd: '/work'));
      await session.appendMessage(UserMessage.text('big'));
      // One HUGE final read — it sits inside the protected tail, so the
      // hide passes cannot touch it; only the trim valve can bound it.
      await session.appendMessage(
        _assistant(
          'huge read',
          calls: [
            const ToolCall(
              id: 'huge',
              name: 'read',
              arguments: {'path': 'huge.txt'},
            ),
          ],
        ),
      );
      await session.appendMessage(_result('huge', 'read', 'H' * 60000));
      final state = _state(await session.buildContextMessages());
      final relief = EmergencyRelief(
