// gh-1680 follow-up (PR #1695 coverage): the CLI-side message-cap heal
// glue executed IN-PROCESS — `_relieveMessageCap` (the host-relief
// extension), `_persistModelCaps` (AC2 boot-load), `_CliMessageCapPolicy`
// and the cap gate. These lines only run inside an `AgentCli` whose agent
// loop heals a classified cap refusal; the PTY/AOT legs execute them in a
// subprocess the coverage harness cannot see, so the in-process drive
// here is the measurement that counts.
//
// Reactive leg: a first request answered with a `array length N exceeds
// limit M` refusal → the CLI learns cap 2048, persists it under
// `<homeDir>/.fah/model_caps.json`, runs one relief pass, coalesces the
// armed payload and retries ONCE into a completing answer.
import 'dart:convert';
import 'dart:io';

import 'package:flutter_agent_harness/flutter_agent_harness.dart';
import 'package:test/test.dart';

import 'agent_cli_test_support.dart';

const _model = Model(
  id: 'test-model',
  api: 'test-api',
  provider: 'test-provider',
  baseUrl: 'https://example.test',
  contextWindow: 200000,
  maxTokens: 4096,
);

const _incident = '400 messages: array length 2049 exceeds limit 2048';
const _checkpointReply =
    'CAP CHECKPOINT: earlier turns folded into this summary.';

AssistantMessage _assistant({
  List<ContentBlock> content = const [],
  StopReason stopReason = StopReason.stop,
  String? errorMessage,
}) {
  return AssistantMessage(
    content: content,
    api: 'test-api',
    provider: 'test-provider',
    model: 'test-model',
    usage: Usage.zero,
    stopReason: stopReason,
    errorMessage: errorMessage,
    timestamp: DateTime.utc(2026),
  );
}

List<AssistantMessageEvent> _textTurn(String text) {
  final empty = _assistant();
  final partial = _assistant(content: [TextContent(text: text)]);
  return [
    StartEvent(partial: empty),
    TextStartEvent(contentIndex: 0, partial: empty),
    TextDeltaEvent(contentIndex: 0, delta: text, partial: partial),
    DoneEvent(reason: StopReason.stop, message: partial),
  ];
}

List<AssistantMessageEvent> _capRefusalTurn(String error) {
  final msg = _assistant(stopReason: StopReason.error, errorMessage: error);
  return [
    StartEvent(partial: msg),
    ErrorEvent(reason: StopReason.error, error: msg),
  ];
}

/// Judge/checkpoint-aware fake: the structured compaction passes get
/// deterministic answers (hide nothing, canned summary); REAL agent turns
/// pop [answers] in order.
final class _CapAwareStream {
  final answers = <List<AssistantMessageEvent>>[];
  final contexts = <Context>[];
  var _answered = 0;

  AssistantMessageEventStream call(
    Model model,
    Context context, {
    CancelToken? cancelToken,
  }) {
    contexts.add(
      Context(
        systemPrompt: context.systemPrompt,
        messages: List.of(context.messages),
        tools: context.tools,
      ),
    );
    final prompt = [
      for (final m in context.messages)
        switch (m) {
          UserMessage() => messageText(m),
          AssistantMessage() =>
            m.content.whereType<TextContent>().map((b) => b.text).join(),
          _ => '',
        },
    ].join('\n');
    final List<AssistantMessageEvent> turn;
    if (prompt.contains('context-hygiene judge')) {
      turn = _textTurn('[]');
    } else if (prompt.contains('Write a checkpoint')) {
      turn = _textTurn(_checkpointReply);
    } else {
      turn = answers[_answered++ % answers.length];
    }
    final stream = AssistantMessageEventStream();
    for (final event in turn) {
      stream.push(event);
    }
    stream.end();
    return stream;
  }

  /// The agent-turn requests (the compaction judge/checkpoint calls are
  /// filtered out by their own system prompts).
  Iterable<Context> get turnRequests => contexts.where(
    (context) => (context.systemPrompt ?? '').startsWith('You are Fa'),
  );
}

Future<void> waitUntil(
  bool Function() condition,
  String Function() describe,
) async {
  for (var i = 0; i < 5000; i++) {
    if (condition()) return;
    await Future<void>.delayed(const Duration(milliseconds: 5));
  }
  fail('timed out waiting: ${describe()}');
}

void main() {
  late Directory tempHome;
  late FakeCliIO io;

  setUp(() {
    tempHome = Directory.systemTemp.createTempSync('fa_cap_cli_home_');
    io = FakeCliIO();
  });
  tearDown(() {
    io.close();
    tempHome.deleteSync(recursive: true);
  });

  File capsFile() => File('${tempHome.path}/.fah/model_caps.json');

  AgentCli cli(MemoryExecutionEnv env, _CapAwareStream stream) => AgentCli(
    config: AgentCliConfig(
      model: _model,
      apiKey: '[REDACTED:Sensitive-Value]',
      env: env,
      sessionRoot: '/sessions',
      providerKind: 'openai-completions',
      skillsAccess: SkillsAccess.granted,
      homeDir: tempHome.path,
    ),
    io: io,
    streamFunction: stream.call,
  );

  test(
    'a cap refusal heals: learn, persist, relieve, coalesce, retry',
    () async {
      final env = MemoryExecutionEnv(cwd: '/work', shell: FakeShell());
      // Suppress session-start memory maintenance (suite pattern).
      await env.writeFile('/work/.fah/memory/.last_maintenance', '');
      final stream = _CapAwareStream()
        ..answers.addAll([
          _capRefusalTurn(_incident),
          _textTurn('healed reply'),
        ]);
      final agent = cli(env, stream);

      final run = agent.run();
      io.sendLine('go');
      await waitUntil(
        () => stream.turnRequests.length >= 2 && !agent.isBusy,
        () =>
            'heal: turns=${stream.turnRequests.length} '
            'calls=${stream.contexts.length} out=${io.out}',
      );
      io.sendLine('/exit');
      await run;

      // The retry completed the turn.
      expect(io.out.toString(), contains('healed reply'));

      // The parsed cap persisted for the next boot (AC2) — the CLI-side
      // persistence glue, not just the in-memory loop store.
      expect(capsFile().existsSync(), isTrue, reason: io.out.toString());
      final persisted =
          jsonDecode(capsFile().readAsStringSync()) as Map<String, dynamic>;
      expect(
        persisted.values
            .whereType<Map>()
            .map((r) => r['maxMessages'])
            .whereType<int>(),
        contains(2048),
      );
    },
  );
}

  test('auto-compacts after a turn over the threshold', () async {
    // Window 16384 (forWindow: reserve 4096, keep 20000, trigger at 12288).
    // Every request also carries ~8.4k of system prompt + tool schemas
    // (counted while the transcript is unanchored), so the first request
    // (~8.4k) still passes the loop's mid-turn over-window guard, while
    // the ~5000-token answer pushes the post-turn request size over the
    // compaction threshold.
    const tinyWindow = Model(
      id: 'tiny',
      api: 'test-api',
      provider: 'test-provider',
      baseUrl: 'https://example.test',
      contextWindow: 16384,
      maxTokens: 4096,
    );
    final fake = FakeStreamFunction([
      textTurn('a' * 20000),
      textTurn('AUTO SUMMARY'),
    ]);
    // Issue #287: pins the classic rollback's CompactionRecord outcome.
    final cli = cliFor(
      fake.call,
      model: tinyWindow,
      compactionEngine: CompactionEngine.classic,
    );
    final run = cli.run();

    io.sendLine('q');
    await waitForIt(() => fake.calls == 2, reason: 'summarizer called');
    await waitForIt(() => io.out.toString().contains('● auto-compacted'));
    io.sendLine('/exit');
    await run;

    final entries = await sessionEntries();
    // The relief's attempt plus the post-run compaction each roll back.
    expect(entries.whereType<CompactionRecord>(), isNotEmpty);
  });

  test('over-window guard auto-compacts and continues the turn', () async {
    // The guard refuses to send when a mid-run tool result balloons the
    // outgoing request past the window. Stopping there is only half the
    // job: after the post-run auto-compaction frees the window, the CLI
    // must CONTINUE the interrupted task on its own — exactly once —
    // instead of idling until the user types "continue".
    const window32k = Model(
      id: 'test-model',
      api: 'test-api',
      provider: 'test-provider',
      baseUrl: 'https://example.test',
      contextWindow: 32768,
      maxTokens: 4096,
    );
    final fake = FakeStreamFunction([
      // 1. Three tool calls whose outputs (~8200 tokens each) balloon the
      //    next request past the window (3 × 8200 + the ~8.4k system
      //    prompt/tool-schema overhead > 32768) — each one is droppable
      //    (over the 20000-token keep region together) so the summarizer
      //    can free the window.
      toolTurn([
        ToolCall(
          id: 'c1',
          name: 'bash',
          arguments: const {'command': 'cat a.log'},
        ),
        ToolCall(
          id: 'c2',
          name: 'bash',
          arguments: const {'command': 'cat b.log'},
        ),
        ToolCall(
          id: 'c3',
          name: 'bash',
          arguments: const {'command': 'cat c.log'},
        ),
      ]),
      // 2. Consumed by the mid-run relief's no-op compaction attempt
      //    (issue #387: the guard offers the host one synchronous pass
      //    before erroring; the classic engine's rollback happens
      //    post-run here).
      textTurn('S'),
      // 3. Consumed as the post-run compaction summary.
      textTurn('S'),
      // 4. After the guard + compaction + auto-continue, the model
      //    finishes the task against the compacted transcript.
      textTurn('continued after compaction'),
    ]);
    final shell = FakeShell(stdout: 'x' * 32800);
    final shellEnv = MemoryExecutionEnv(cwd: '/work', shell: shell);
    // Issue #287: the guard→classic-summarizer→auto-continue recovery is
    // the classic rollback path under test.
    final cli = cliFor(
      fake.call,
      model: window32k,
      envOverride: shellEnv,
      compactionEngine: CompactionEngine.classic,
    );
    final run = cli.run();

    io.sendLine('go');
    await waitForIt(
      () => fake.calls >= 4 && !cli.isBusy,
      reason: 'auto-continuation after guard + compaction',
    );
    io.sendLine('/exit');
    await run;

    final output = io.out.toString();
    // The guard fired — as a calm yellow note, never the red error line
    // (auto-compaction recovers right after)…
    expect(output, contains('note: Context window exhausted'));
    expect(output, isNot(contains('error: Context window exhausted')));
    expect(output, contains('● auto-compacted'));
    // …and the turn visibly continued on its own.
    expect(output, contains('auto-compacted; continuing'));
    // request 1 (tool turn) + the relief's no-op summarizer attempt +
    // the post-run summarizer + the continuation request.
    expect(fake.calls, greaterThanOrEqualTo(4));
    final repo = JsonlSessionRepo(fs: shellEnv, sessionsRoot: '/sessions');
    final sessions = await repo.list(cwd: '/work');
    final session = await repo.open(sessions.first);
    final entries = await session.getEntries();
    // The relief's attempt plus the post-run compaction each roll back.
    expect(entries.whereType<CompactionRecord>(), isNotEmpty);
    // The continuation prompt lands as a system notice (user-role record
