import 'package:flutter_agent_harness/flutter_agent_harness.dart';
import 'package:test/test.dart';

import 'agent_cli_test_support.dart';

void main() {
  test('debug keepN relief flow', timeout: const Timeout(Duration(seconds: 120)), () async {
    final env = MemoryExecutionEnv(cwd: '/work');
    await env.writeFile('/work/.fah/memory/.last_maintenance', '');
    env.writeFile('big.txt', List.filled(1000, 'x' * 45).join('\n'));
    env.writeFile('mid.txt', List.filled(500, 'y' * 40).join('\n'));
    env.writeFile('big2.txt', List.filled(1000, 'z' * 45).join('\n'));
    final io = FakeCliIO();
    final fake = FakeStreamFunction([
      toolTurn([const ToolCall(id: 't1', name: 'read', arguments: {'path': 'big.txt'})]),
      toolTurn([const ToolCall(id: 't2', name: 'read', arguments: {'path': 'mid.txt'})]),
      toolTurn([const ToolCall(id: 't3', name: 'read', arguments: {'path': 'big2.txt'})]),
      textTurn('continuing after the relief'),
    ]);
    final cli = AgentCli(
      config: AgentCliConfig(
        model: const Model(id: 'tiny-window', api: 'test-api', provider: 'test-provider',
            baseUrl: 'https://example.test', contextWindow: 12000, maxTokens: 4096),
        apiKey: '[REDACTED:Sensitive-Value]',
        env: env, sessionRoot: '/sessions', providerKind: 'openai-completions',
        homeDir: '/work/home',
        compactionEngine: CompactionEngine.classic,
        compactionSettings: const CompactionSettings(
            enabled: true, reserveTokens: 100, keepRecentTokens: 100000),
      ),
      io: io,
      streamFunction: fake.call,
    );
    final exitCode = await cli.runHeadless('count the words');
    await io.close();
    await cli.flushDiagnosticLog();
    print('=== exitCode=$exitCode calls=${fake.calls}');
    final log = await env.readTextFile('/work/home/.fah/logs/fa.log');
    print('=== FALOG BEGIN');
    print(log.isOk ? log.valueOrNull : 'missing');
    print('=== FALOG END');
    final repo = JsonlSessionRepo(fs: env, sessionsRoot: '/sessions');
    final sessions = await repo.list(cwd: '/work');
    final session = await repo.open(sessions.first);
    final entries = await session.getEntries();
    print('=== ENTRIES: ${[for (final e in entries) e.runtimeType.toString()]}');
  });
}

