/// of those results succeeded.
(int, bool, bool) _groupWeight(
  _LedgerView view,
  Map<String, SessionRecord> byId,
  Set<String> group,
) {
  var tokens = 0;
  var hasResult = false;
  var hasSuccess = false;
  for (final id in group) {
    final other = byId[id];
    if (other is! MessageRecord) continue;
    final message = other.message;
    if (message is ToolResultMessage) {
      hasResult = true;
      if (!message.isError) hasSuccess = true;
    }
    final seq = view.seqs.seqOf(id);
    if (seq != null) tokens += view.ledger.entryAtSeq(seq)?.tokens ?? 0;
